import { levels } from './levels-draft.mjs'

const DIRS = [[0,-1],[0,1],[-1,0],[1,0]]

function parse(src) {
  const rows = src.split('\n')
  const h = rows.length
  const w = Math.max(...rows.map(r => r.length))
  const walls = new Set(), goals = new Set(), boxes = []
  let player = null
  for (let y=0;y<h;y++) {
    for (let x=0;x<w;x++) {
      const c = rows[y][x] ?? ' '
      const k = y*w+x
      if (c === '#') walls.add(k)
      if (c === '.' || c === '*' || c === '+') goals.add(k)
      if (c === '$' || c === '*') boxes.push(k)
      if (c === '@' || c === '+') player = k
    }
  }
  return { w,h,rows,walls,goals,boxes,player }
}

function keyOf(boxes, player) {
  return boxes.slice().sort((a,b)=>a-b).join(',') + '|' + player
}

function solve(lv, maxStates=4_000_000) {
  const {w,h,walls,goals,boxes,player} = lv
  const goalCount = goals.size
  if (boxes.length !== goalCount) return {error:`boxes ${boxes.length} != goals ${goalCount}`}
  if (player == null) return {error:'no player'}
  const startBoxes = boxes.slice().sort((a,b)=>a-b)
  const startKey = keyOf(startBoxes, player)
  const q = [{boxes:startBoxes, player, depth:0}]
  let qi = 0
  const seen = new Map([[startKey, 0]])
  let states = 0
  while (qi < q.length) {
    const cur = q[qi++]
    states++
    if (states > maxStates) return {error:`too many states (${states})`}
    if (cur.boxes.every(b => goals.has(b))) return {moves: cur.depth, states}
    const px = cur.player % w, py = Math.floor(cur.player / w)
    const boxSet = new Set(cur.boxes)
    for (const [dx,dy] of DIRS) {
      const nx = px+dx, ny=py+dy
      if (nx<0||ny<0||nx>=w||ny>=h) continue
      const nk = ny*w+nx
      if (walls.has(nk)) continue
      let nextBoxes = cur.boxes
      if (boxSet.has(nk)) {
        const bx=nx+dx, by=ny+dy
        if (bx<0||by<0||bx>=w||by>=h) continue
        const bk = by*w+bx
        if (walls.has(bk) || boxSet.has(bk)) continue
        nextBoxes = cur.boxes.map(b => b===nk?bk:b).sort((a,b)=>a-b)
      }
      const k = keyOf(nextBoxes, nk)
      if (seen.has(k)) continue
      seen.set(k, cur.depth+1)
      q.push({boxes:nextBoxes, player:nk, depth:cur.depth+1})
    }
  }
  return {error:'unsolvable', states}
}

levels.forEach((src,i) => {
  const lv = parse(src)
  const r = solve(lv)
  console.log(`L${String(i+1).padStart(2)} ${lv.w}x${lv.h} boxes=${lv.boxes.length}`, r)
})

