    if(c==='#')walls.add(k)
    if(['.','*','+'].includes(c))goals.add(k)
    if(['$','*'].includes(c))boxes.push(k)
    if(['@','+'].includes(c))player=k
  }
  return{w,h,walls,goals,boxes,player}
}
function keyOf(boxes,player){return boxes.slice().sort((a,b)=>a-b).join(',')+'|'+player}
function solve(lv,maxStates=3_000_000){
  const{w,walls,goals,boxes,player}=lv
  if(boxes.length!==goals.size)return{error:`boxes ${boxes.length} goals ${goals.size}`}
  const q=[{boxes:boxes.slice().sort((a,b)=>a-b),player,depth:0}]
  let qi=0,states=0
  const seen=new Set([keyOf(q[0].boxes,player)])
  while(qi<q.length){
    const cur=q[qi++];states++
    if(states>maxStates)return{error:'too many',states}
    if(cur.boxes.every(b=>goals.has(b)))return{moves:cur.depth,states}
    const px=cur.player%w,py=Math.floor(cur.player/w),bset=new Set(cur.boxes)
    for(const[dx,dy]of DIRS){
      const nx=px+dx,ny=py+dy,nk=ny*w+nx
      if(walls.has(nk))continue
      let nb=cur.boxes
      if(bset.has(nk)){
        const bx=nx+dx,by=ny+dy
        if(bx<0||by<0||bx>=w||by>=lv.h)continue
        const bk=by*w+bx
        if(walls.has(bk)||bset.has(bk))continue
        nb=cur.boxes.map(b=>b===nk?bk:b).sort((a,b)=>a-b)
      }
      const k=keyOf(nb,nk)
      if(seen.has(k))continue
      seen.add(k);q.push({boxes:nb,player:nk,depth:cur.depth+1})
    }
  }
  return{error:'unsolvable',states}
}
